// A9 sensors HAL: AIDL android.hardware.sensors V3 (NDK backend generated by build.sh from the
// frozen V3 API) over sensors_core (SNS client over QRTR) and fmq_writer (event queue).
// Light, accel, magnetic field and proximity. Kill switch: without persist.a9.sensors=1 the HAL still registers
// (so sensorservice never waits on it) but exposes no sensor and never opens a QRTR socket.
#include <aidl/android/hardware/sensors/BnSensors.h>
#include <android/binder_manager.h>
#include <android/binder_process.h>
#include <android/log.h>
#include <sys/system_properties.h>

#include <chrono>
#include <cstdio>
#include <cstring>
#include <mutex>
#include <thread>
#include <type_traits>

#include "fmq_writer.h"
#include "s2-qrtr.h"
#include "sensors_core.h"

#define LOG_TAG "sensors-a9"
#define ALOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)
#define ALOGW(...) __android_log_print(ANDROID_LOG_WARN, LOG_TAG, __VA_ARGS__)
#define ALOGE(...) __android_log_print(ANDROID_LOG_ERROR, LOG_TAG, __VA_ARGS__)

using namespace aidl::android::hardware::sensors;
using aidl::android::hardware::common::fmq::MQDescriptor;
using aidl::android::hardware::common::fmq::SynchronizedReadWrite;
using ndk::ScopedAStatus;

// The event queue carries the generated @FixedSize Event by value (as libfmq's AidlMessageQueue does).
static_assert(std::is_same<Event::fixed_size, std::true_type>::value, "Event must be @FixedSize");
static_assert(sizeof(Event) % alignof(int64_t) == 0, "Event size");

namespace {

constexpr int kReadyWaitMs = 20000;   // vendor.a9.sensors.ready from a9-sensors.sh
constexpr int kLookupMs = 3000, kAttrMs = 3000;

std::string prop(const char* name) {
    char v[PROP_VALUE_MAX] = {0};
    __system_property_get(name, v);
    return v;
}

// stdio stream into logcat, so the shared C client's lines land in the log
FILE* logStream() {
    auto w = [](void*, const char* buf, int n) -> int {
        std::string s(buf, size_t(n));
        while (!s.empty() && s.back() == '\n') s.pop_back();
        if (!s.empty()) __android_log_write(ANDROID_LOG_INFO, LOG_TAG, s.c_str());
        return n;
    };
    FILE* f = funopen(nullptr, nullptr, w, nullptr, nullptr);   // bionic: write-only stream into logcat
    if (f) setvbuf(f, nullptr, _IOLBF, 0);
    return f;
}

ScopedAStatus bad() { return ScopedAStatus::fromServiceSpecificError(ISensors::ERROR_BAD_VALUE); }

class SensorsA9 : public BnSensors {
  public:
    SensorsA9(const s2_link* link, a9sensors::TimeBase* tb, FILE* log)
        : core_(link, tb, [this](const std::vector<a9sensors::Ev>& ev) { deliver(ev); }, log) {}

    void discover() {
        size_t n = core_.discover(kLookupMs, kAttrMs);
        ALOGI("discovery: %zu sensor(s) exposed", n);
    }

    ScopedAStatus getSensorsList(std::vector<SensorInfo>* out) override {
        out->clear();
        for (const auto& s : core_.sensors()) {
            SensorInfo i;
            const auto& d = s.def;
            i.sensorHandle = d.handle;
            i.name = d.name;
            i.vendor = s.attrs.vendor[0] ? s.attrs.vendor : d.vendor;
            i.version = d.version;
            i.type = SensorType(d.type);
            i.typeAsString = "";
            i.maxRange = d.maxRange;
            i.resolution = d.resolution;
            i.power = d.powerMa;
            i.minDelayUs = d.minDelayUs;
            i.maxDelayUs = d.maxDelayUs;
            i.fifoReservedEventCount = d.fifoReserved;
            i.fifoMaxEventCount = d.fifoMax;
            i.requiredPermission = "";
            i.flags = (d.onChange ? a9sensors::kFlagOnChange : 0) | (d.wakeUp ? a9sensors::kFlagWakeUp : 0);
            out->push_back(std::move(i));
        }
        return ScopedAStatus::ok();
    }

    ScopedAStatus initialize(const MQDescriptor<Event, SynchronizedReadWrite>& eventQ,
                             const MQDescriptor<int32_t, SynchronizedReadWrite>& /*wakeLockQ*/,
                             const std::shared_ptr<ISensorsCallback>& cb) override {
        // Per the interface: a (re)initialize deactivates every sensor first.
        core_.stopAll();
        std::vector<int> fds;
        for (const auto& fd : eventQ.handle.fds) fds.push_back(fd.get());
        std::vector<a9sensors::Grantor> g;
        for (const auto& x : eventQ.grantors) g.push_back({x.fdIndex, x.offset, x.extent});
        std::lock_guard<std::mutex> l(qm_);
        if (q_.init(fds, g, eventQ.quantum, sizeof(Event))) {
            ALOGE("event queue descriptor refused (quantum %d, element %zu, %zu grantors)", eventQ.quantum, sizeof(Event),
                  g.size());
            return ScopedAStatus::fromServiceSpecificError(ISensors::ERROR_BAD_VALUE);
        }
        cb_ = cb;   // only non-wake-up sensors: the wake-lock queue is never written
        ALOGI("initialized: event queue %zu events", q_.capacityElements());
        return ScopedAStatus::ok();
    }

    ScopedAStatus activate(int32_t h, bool en) override {
        int rc = core_.activate(h, en);
        if (rc) ALOGW("activate %d %d -> %d", h, en, rc);
        return rc ? bad() : ScopedAStatus::ok();
    }
    ScopedAStatus batch(int32_t h, int64_t p, int64_t l) override { return core_.batch(h, p, l) ? bad() : ScopedAStatus::ok(); }
    ScopedAStatus flush(int32_t h) override { return core_.flush(h) ? bad() : ScopedAStatus::ok(); }

    ScopedAStatus setOperationMode(ISensors::OperationMode mode) override {
        return mode == ISensors::OperationMode::NORMAL ? ScopedAStatus::ok()
                                                       : ScopedAStatus::fromExceptionCode(EX_UNSUPPORTED_OPERATION);
    }
    ScopedAStatus injectSensorData(const Event&) override {
        return ScopedAStatus::fromExceptionCode(EX_UNSUPPORTED_OPERATION);
    }
    ScopedAStatus registerDirectChannel(const ISensors::SharedMemInfo&, int32_t*) override {
        return ScopedAStatus::fromExceptionCode(EX_UNSUPPORTED_OPERATION);
    }
    ScopedAStatus unregisterDirectChannel(int32_t) override {
        return ScopedAStatus::fromExceptionCode(EX_UNSUPPORTED_OPERATION);
    }
    ScopedAStatus configDirectReport(int32_t, int32_t, ISensors::RateLevel, int32_t*) override {
        return ScopedAStatus::fromExceptionCode(EX_UNSUPPORTED_OPERATION);
    }

  private:
    void deliver(const std::vector<a9sensors::Ev>& in) {
        std::vector<Event> out;
        out.reserve(in.size());
        for (const auto& e : in) {
            Event ev;
            ev.sensorHandle = e.handle;
            ev.timestamp = e.timestampNs;
            if (e.flushComplete) {
                ev.sensorType = SensorType::META_DATA;
                Event::EventPayload::MetaData meta;
                meta.what = Event::EventPayload::MetaData::MetaDataEventType::META_DATA_FLUSH_COMPLETE;
                ev.payload.set<Event::EventPayload::Tag::meta>(meta);
            } else if (e.type == a9sensors::kTypeLight || e.type == a9sensors::kTypeProximity) {
                ev.sensorType = SensorType(e.type);
                ev.payload.set<Event::EventPayload::Tag::scalar>(e.v[0]);
            } else if (e.type == a9sensors::kTypeAccelerometer || e.type == a9sensors::kTypeMagneticField) {
                ev.sensorType = SensorType(e.type);
                Event::EventPayload::Vec3 v;
                v.x = e.v[0]; v.y = e.v[1]; v.z = e.v[2];
                v.status = SensorStatus(e.status);
                ev.payload.set<Event::EventPayload::Tag::vec3>(v);
            } else {
                continue;
            }
            out.push_back(ev);
        }
        if (out.empty()) return;
        std::lock_guard<std::mutex> l(qm_);
        if (!q_.valid()) return;
        if (q_.write(out.data(), out.size())) {
            ++dropped_;
            if ((dropped_ & (dropped_ - 1)) == 0) ALOGW("event queue full: %llu batch(es) dropped", (unsigned long long)dropped_);
            return;
        }
        q_.wake(uint32_t(ISensors::EVENT_QUEUE_FLAG_BITS_READ_AND_PROCESS));
    }

    a9sensors::Core core_;
    std::mutex qm_;
    a9sensors::FmqWriter q_;
    std::shared_ptr<ISensorsCallback> cb_;
    unsigned long long dropped_ = 0;
};

// Waits for a9-sensors.sh: true on vendor.a9.sensors.ready=1. Stops early (false) when the
// setup service has already given up (vendor.a9.sensors.state=fail:<step>), so a failed setup
// costs the HAL one poll, not the full kReadyWaitMs (review 79k N5).
bool waitReady(std::string* why) {
    for (int waited = 0; waited < kReadyWaitMs; waited += 200) {
        if (prop("vendor.a9.sensors.ready") == "1") return true;
        const std::string st = prop("vendor.a9.sensors.state");
        if (st.rfind("fail:", 0) == 0) { *why = st; return false; }
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
    }
    *why = "timeout";
    return false;
}

}  // namespace

int main() {
    ABinderProcess_setThreadPoolMaxThreadCount(4);
    ABinderProcess_startThreadPool();
    FILE* log = logStream();
    if (!log) log = stderr;
    static s2_qrtr q;
    static s2_link link{};
    auto tb = a9sensors::realTimeBase();
    const bool enabled = prop("persist.a9.sensors") == "1";
    auto hal = ndk::SharedRefBase::make<SensorsA9>(&link, tb.get(), log);
    if (!enabled) {
        ALOGI("persist.a9.sensors != 1: registering with no sensors (kill switch)");
    } else if (std::string why; !waitReady(&why)) {
        ALOGW("vendor.a9.sensors.ready not set (%s, limit %d ms): no sensors this boot", why.c_str(), kReadyWaitMs);
    } else if (s2_qrtr_init(&q, &link, 5000)) {
        ALOGW("SNS 400 not advertised: no sensors this boot");
    } else {
        hal->discover();
    }
    const std::string name = std::string() + ISensors::descriptor + "/default";
    if (AServiceManager_addService(hal->asBinder().get(), name.c_str()) != STATUS_OK) {
        ALOGE("addService %s failed", name.c_str());
        return 1;
    }
    ALOGI("%s registered", name.c_str());
    ABinderProcess_joinThreadPool();
    return 1;
}
